from collections import OrderedDict


class LRUCache:
    """Fixed-capacity cache that evicts the least recently used entry."""

    def __init__(self, capacity):
        if capacity <= 0:
            raise ValueError("capacity must be positive")
        self.capacity = capacity
        self.entries = OrderedDict()
        self.hits = 0
        self.misses = 0

    def get(self, key, default=None):
        if key not in self.entries:
            self.misses += 1
            return default
        self.hits += 1
        self.entries.move_to_end(key)
        return self.entries[key]

    def put(self, key, value):
        """Store value under key, evicting the oldest entry if full.

        Returns the evicted (key, value) pair, or None if nothing was evicted.
        """
        if key in self.entries:
            self.entries[key] = value
            self.entries.move_to_end(key)
            return None

        self.entries[key] = value
        if len(self.entries) > self.capacity:
            return self.entries.popitem(last=False)
        return None

    def stats(self):
        """Counts of lookups that hit and missed, plus the current entry count.

        A miss is counted for every `get` on an absent key, including keys
        never written.
        """
        return {"hits": self.hits, "misses": self.misses, "size": len(self.entries)}

    def __contains__(self, key):
        return key in self.entries

    def __len__(self):
        return len(self.entries)

    def __repr__(self):
        return f"LRUCache(capacity={self.capacity}, size={len(self.entries)})"
